{"command": "cd /workspace/build && python3 - << 'EOF'
import sys; sys.path.insert(0,'/workspace/build')
import struct, subprocess, json
def call(t,a):
    r = subprocess.run(['ft2','call',t,json.dumps(a)],capture_output=True,text=True)
    return r.stdout.strip()
call('module_new',{'channels':2,'name':'scratch'})

def mkhdr(name, tracker, hsz=276, extra=b'', chans=2, npat=1, nins=1, flags=1, tempo=6, bpm=120):
    out = bytearray()
    out += b"Extended Module: " + name.encode()[:20].ljust(20,b'\x00')
    out += tracker
    out += struct.pack("<H", 0x0104)
    out += struct.pack("<I", hsz)
    out += struct.pack("<8H", 1, 0, chans, npat, nins, flags, tempo, bpm)
    out += struct.pack("<256B", *([0]*256))
    return bytes(out)

# instrument with 0 samples, clone style (33) and mine (29)
ins33 = struct.pack("<I22sBHI", 33, b"sine".ljust(22,b'\x00'), 0, 0, 0)
ins29 = struct.pack("<I22sBH", 29, b"sine".ljust(22,b'\x00'), 0, 0)

def pat(rows=64, ch=2, cells=None):
    import collections
    data = bytearray()
    cells = cells or {}
    for r in range(rows):
        for c in range(ch):
            cell = cells.get((r,c))
            if cell is None:
                data.append(0x80)
            else:
                data += bytes(cell)
    return struct.pack("<IHH", len(data), rows, 0) + bytes(data)

variants = {}
# A: 21-byte tracker (clone), 33-byte instrument
variants['A'] = mkhdr('a', b"\x1aPyKeygen synth v1 ") + pat() + ins33
# B: 20-byte tracker, 29-byte instrument
variants['B'] = mkhdr('b', b"PyKeygen synth v1.0 ") + pat() + ins29
# C: 21-byte tracker, 29-byte instrument
variants['C'] = mkhdr('c', b"\x1aPyKeygen synth v1 ") + pat() + ins29
# D: 20-byte tracker, 33-byte instrument
variants['D'] = mkhdr('d', b"PyKeygen synth v1.0 ") + pat() + ins33
for k,v in variants.items():
    open('/workspace/build/v_%s.xm'%k,'wb').write(v)
    res = call('module_load',{'path':'/workspace/build/v_%s.xm'%k})
    print(k, res[:120])
EOF"}

