def mkhdr(name, tracker, hsz=276, extra=b'', chans=2, npat=1, nins=1, flags=1, tempo=6, bpm=120):
    out = bytearray()
    out += b"Extended Module: " + name.encode()[:20].ljust(20,b'\x00')
    out += tracker
    out += struct.pack("<H", 0x0104)
    out += struct.pack("<I", hsz)
    out += struct.pack("<8H", 1, 0, chans, npat, nins, flags, tempo, bpm)
    out += struct.pack("<256B", *([0]*256))
    return bytes(out)

# instrument with 0 samples, clone style (33) and mine (29)
ins33 = struct.pack("<I22sBHI", 33, b"sine".ljust(22,b'\x00'), 0, 0, 0)
ins29 = struct.pack("<I22sBH", 29, b"sine".ljust(22,b'\x00'), 0, 0)

def pat(rows=64, ch=2, cells=None):
    import collections
    data = bytearray()
    cells = cells or {}
    for r in range(rows):
        for c in range(ch):
            cell = cells.get((r,c))
            if cell is None:
                data.append(0x80)
            else:
                data += bytes(cell)
    return struct.pack("<IHH", len(data), rows, 0) + bytes(data)

