def hdr(name=b'mod', chans=2, npat=1, nins=1, tempo=6, bpm=125, flags=1, pad=0x20):
    out = bytearray()
    out += b"Extended Module: " + name.ljust(20, bytes([pad]))
    out += b"\x1aPyKeygen synth v1.0"
    out += struct.pack("<H", 0x0104)
    out += struct.pack("<I", 276)
    out += struct.pack("<8H", 1, 0, chans, npat, nins, flags, tempo, bpm)
    out += struct.pack("<256B", *([0]*256))
    return out
def pat(rows=4, ch=2, cells=None):
    cells = cells or {}
    data = bytearray()
    for r in range(rows):
        for c in range(ch):
            data += bytes(cells.get((r,c)) or b'\x80')
    return struct.pack("<IHH", len(data), rows, 0) + bytes(data)
ins33 = struct.pack("<I22sBHI", 33, b"sine".ljust(22,b'\x00'), 0, 0, 0)
ins29 = struct.pack("<I22sBH", 29, b"sine".ljust(22,b'\x00'), 0, 0)

test("space-padded name + bpm125", hdr() + pat() + ins33)
test("null-padded name + bpm125", hdr(pad=0) + pat() + ins33)
test("space + ins29", hdr() + pat() + ins29)
